sys_script_include.script:
function AppTouch(vApp)
{
	var grApp = GetAppRecord(vApp);
	if (IsValidRecord(grApp) == false)
	{
		return false;
	}
	Log('AppTouch: START: '+grApp.name);

	var strLog = '';

	strLog += '\nBEFORE:';
	strLog += RenderValue(grApp);
	var strName = GetStringValue(grApp.name);
	RecordSetValue('sys_app',grApp.sys_id,'name','TOUCH '+strName);
	RecordSetValue('sys_app',grApp.sys_id,'name',strName);
	strLog += '\n\nAFTER:';
	strLog += RenderValue(GetRecord('sys_app',grApp.sys_id));

	var grMetadata = new GlideRecord('sys_metadata');
	grMetadata.addQuery('sys_scope','=',grApp.sys_id);
	grMetadata.query();
	while (grMetadata.next() == true)
	{
		strLog += '\n\nBEFORE:';
		strLog += RenderValue(grMetadata);

		var strSysName = GetStringValue(grMetadata.sys_name);
		RecordSetValue('sys_metadata',grMetadata.sys_id,'sys_name','TOUCH '+strSysName);
		RecordSetValue('sys_metadata',grMetadata.sys_id,'sys_name',strSysName);
		strLog += '\n\nAFTER:';
		strLog += RenderValue(GetRecord('sys_metadata',grMetadata.sys_id));
	}
	Log(strLog);
	Log('AppTouch: END: '+grApp.name);
	return true;
}
